svg.script:
    (function () {
      var SVGNS = "http://www.w3.org/2000/svg";
      var XHTMLNS = "http://www.w3.org/1999/xhtml";
      var here = new URL("../", location.href).href;

      function fail(msg) {
        var t = document.querySelector("text");
        if (t) t.textContent = "Could not load page: " + msg;
      }

      // ask the parser whether a <base> tag is really there. a substring check
      // is fooled by page source that merely mentions the tag - index.html does,
      // in a comment, so the naive test skipped the real insertion and every
      // relative path in the frame resolved against /svg/ instead of the root.
      function hasBase(html) {
        try {
          return !!new DOMParser().parseFromString(html, "text/html").querySelector("base");
        } catch (e) {
          return true; // cannot tell: leave the html alone
        }
      }

function ensureBase(html, href) {
        if (hasBase(html)) return html;
        var tag = '<base href="' + href + '">';
        return /<head[^>]*>/i.test(html)
          ? html.replace(/<head[^>]*>/i, function (m) {
              return m + tag;
            })
          : tag + html;
      }

      if (navigator.serviceWorker) {
        navigator.serviceWorker.register("../sw.js", {
          updateViaCache: "none"
        }).catch(function (e) {
          console.warn("Service worker:", e.message);
        });
      }

      fetch(here + "index.html", { cache: "no-store" })
        .then(function (r) {
          if (!r.ok) throw new Error(r.status + " " + r.statusText);
          return r.text();
        })
        .then(function (html) {
          html = ensureBase(html, here);

          var holder = document.createElementNS(SVGNS, "foreignObject");
          holder.setAttribute("x", "0");
          holder.setAttribute("y", "0");
          holder.setAttribute("width", "100%");
          holder.setAttribute("height", "100%");

          var frame = document.createElementNS(XHTMLNS, "iframe");
          frame.setAttribute("title", "m's games and stuff");
          frame.setAttribute("style",
            "display:block;width:100%;height:100%;border:0;margin:0;background:#050507");

          holder.appendChild(frame);
          document.documentElement.appendChild(holder);
          frame.srcdoc = html;

          var rect = document.querySelector("rect");
          if (rect) rect.remove();
          var text = document.querySelector("text");
          if (text) text.remove();
        })
        .catch(function (e) {
          fail(e.message);
        });
    })();
